import {storms} from './data.js';
const main=document.querySelector('main');let destroySim=null;let routeEpoch=0;
const card=(s,i)=>`<a class="card" href="/storms/${s.id}/" style="--accent:${s.color}"><div class="card-image"><img src="/assets/${s.id}.webp" alt="המחשה של ${s.name}" ${i>2?'loading="lazy"':''} width="1672" height="941"><span class="tag">${s.tag}</span></div><div class="card-body"><div class="card-title"><h2>${s.name}</h2><span lang="en" dir="ltr">${s.en}</span></div><p>${s.short}</p><div class="card-link"><span>לגלות את הסופה · סימולטור תלת־ממדי</span><span aria-hidden="true">←</span></div></div></a>`;
async function render(){const epoch=++routeEpoch;destroySim?.();destroySim=null;const id=location.pathname.split('/').filter(Boolean)[1];const s=storms.find(x=>x.id===id);document.documentElement.style.setProperty('--accent',s?.color||'#80ddd8');
 if(!s){document.title='אטלס הסופות';main.innerHTML=`<section class="home-top"><div><span class="eyebrow">הטבע בתנועה</span><h1>להיכנס לעין הסערה.</h1><p>גלו איך נולדות סופות, מה מניע אותן ואיך הן נראות מבפנים.</p></div><div class="count"><b>07</b>סופות לחקור</div></section><section class="catalog" aria-label="סוגי סופות">${storms.map(card).join('')}</section><p class="catalog-note">שבעה סוגים מרכזיים של סופות טבע. חלקם יכולים להתרחש יחד, וקיימים גם סוגים ותתי־סוגים נוספים.</p>`;return;}
 document.title=s.name+' | אטלס הסופות';const index=storms.indexOf(s),next=storms[(index+1)%storms.length];main.innerHTML=`<nav class="breadcrumbs" aria-label="מיקום באתר"><a href="/">כל הסופות</a><span aria-hidden="true">/</span><span>${s.name}</span></nav><section class="detail-head"><div><span class="eyebrow" lang="en" dir="ltr">${s.en} / 0${index+1}</span><h1>${s.name}</h1><p>${s.intro}</p></div><figure class="detail-photo"><img src="/assets/${s.id}.webp" alt="תמונה מייצגת של ${s.name}" width="1672" height="941"><figcaption>המחשה שנוצרה בבינה מלאכותית</figcaption></figure></section><section aria-labelledby="sim-title"><div class="section-title"><h2 id="sim-title">הסופה, בתלת־ממד</h2><span>סובבו את המבט. שנו את העוצמה.</span></div><div class="sim-box"><div class="sim-layout"><div class="viewport" id="viewport"><span class="sim-badge">${s.tag}</span><div class="canvas-help">גרירה לסיבוב · גלילה או צביטה להתקרבות · מקשי חצים לסיבוב</div></div><div class="controls"><h3>שליטה בסופה</h3><div class="range-control"><label class="control-label" for="intensity">עוצמת ההדמיה <output id="intensity-value">50%</output></label><input id="intensity" type="range" min="10" max="100" value="50" step="1"></div><button class="button primary" id="pause">השהיית הסופה</button><button class="button" id="reset">איפוס התצוגה ↺</button><div class="view-buttons"><button class="button" id="zoom-in" aria-label="התקרבות">＋</button><button class="button" id="zoom-out" aria-label="התרחקות">−</button></div><div class="sound-controls"><button class="button" id="sound-toggle" aria-pressed="false">הפעלת צלילי הסופה</button><label class="control-label" for="sound-volume">עוצמת הקול <output id="sound-volume-value">35%</output></label><input id="sound-volume" type="range" min="0" max="100" value="35"><span id="sound-status" role="status">הקול כבוי</span></div><p>המחשה לימודית מפושטת. הגדלים והמהירויות אינם מדידה של סופה אמיתית.</p></div></div><p class="sim-description">${s.sim}</p></div></section><div class="article-grid"><section><h2>איך זה נוצר?</h2><ol class="steps">${s.steps.map(t=>`<li>${t}</li>`).join('')}</ol></section><section><h2>כדאי להכיר</h2><div class="facts">${s.facts.map(([a,b])=>`<div class="fact"><span>${a}</span><strong>${b}</strong></div>`).join('')}</div><div class="note"><b>מבט מקרוב</b>${s.note}</div><a class="source" href="${s.source}" target="_blank" rel="noopener">מקור: ${s.sourceName} ↗</a></section></div><nav class="next-nav" aria-label="ניווט בין סופות"><a href="/">→ חזרה לכל הסופות</a><a href="/storms/${next.id}/">לסופה הבאה: ${next.name} ←</a></nav>`;
 try{const {createSimulator}=await import('/sim.js');if(epoch!==routeEpoch)return;destroySim=createSimulator(document.getElementById('viewport'),s.id);}catch(e){if(epoch!==routeEpoch)return;document.getElementById('viewport').insertAdjacentHTML('beforeend','<p class="fallback">התצוגה התלת־ממדית אינה זמינה בדפדפן הזה. נסו לפתוח את העמוד ב־Chrome מעודכן. התמונה וההסברים נשארים זמינים.</p>');document.querySelectorAll('.controls button,.controls input').forEach(el=>el.disabled=true);console.error(e);}
}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||a.origin!==location.origin||a.hash||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||a.target)return;e.preventDefault();history.pushState({},'',a.pathname);render();window.scrollTo(0,0);main.tabIndex=-1;main.focus({preventScroll:true});});window.addEventListener('popstate',render);render();
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});const dlg=document.querySelector('#install-dialog');document.querySelector('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;return;}const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;document.querySelector('#install-info').innerHTML=standalone?'<p>היישום כבר פתוח במצב מותקן.</p>':'<p><b>Android:</b> פתחו את הקישור בדפדפן Chrome, לחצו על תפריט שלוש הנקודות ובחרו ״התקנת אפליקציה״ או ״הוספה למסך הבית״.</p><p><b>iPhone:</b> פתחו ב־Safari, לחצו על שיתוף ובחרו ״הוספה למסך הבית״.</p><p>אם פתחתם מתוך ChatGPT, עברו תחילה לדפדפן החיצוני. לאחר טעינה ושמירה ראשונית, התוכן זמין גם ללא חיבור.</p>';dlg.showModal();};document.querySelectorAll('.close,.close-dialog').forEach(b=>b.onclick=()=>dlg.close());dlg.addEventListener('click',e=>{if(e.target===dlg)dlg.close();});if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(console.error);
